WITH "__duckstream_0" AS (SELECT t.c0 AS c0, CASE WHEN t.c1 IS NULL OR t.c2 IS NULL THEN NULL WHEN t.c2 >= 1 THEN substring(t.c1, t.c2) ELSE error('SUBSTRING bounds outside positive-start/nonnegative-length profile') END AS c1, CASE WHEN t.c1 IS NULL OR t.c2 IS NULL OR t.c3 IS NULL THEN NULL WHEN t.c2 >= 1 AND t.c3 >= 0 THEN substring(t.c1, t.c2, t.c3) ELSE error('SUBSTRING bounds outside positive-start/nonnegative-length profile') END AS c2 FROM (SELECT "id" AS c0, "s" AS c1, "first" AS c2, "width" AS c3 FROM "substring_source") t)
SELECT CAST(result.c0 AS INTEGER) AS "id", CAST(result.c1 AS VARCHAR) AS "suffix", CAST(result.c2 AS VARCHAR) AS "part" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2 FROM "__duckstream_0" v) result;
